-- R1b reads (9 October 2026): the open-question table and the predicates that decide what Grant sees. READ-ONLY, single selects,
-- run through the read-only endpoint by `ALLOW_PRODUCTION_CHECKS=1 npx tsx scripts/release/preflight-read.ts --file=docs/audit/V1-R1B-NEEDS-ME-QUERIES-2026-10-09.sql`.
-- Discovery statements read catalogue text (column names, view and function source); the rest are AGGREGATES: counts and code-valued
-- categories only. None selects a question's text, a person, an address or an identifier.
-- The read-only role may not execute app.* functions (42501), so the view public.needs_me cannot be read; app.harness_job is RESTATED
-- inline below (N20 onward) from its definition (N03), and the restatement is compared with the unfiltered table.

-- N01 columns of public.blockers.
select column_name, data_type from information_schema.columns where table_schema = 'public' and table_name = 'blockers' order by ordinal_position;

-- N02 the definition of the needs_me view (what he is shown).
select pg_get_viewdef('public.needs_me'::regclass, true) as def;

-- N03 the source of the harness and origin predicates the view uses.
select p.proname, pg_get_functiondef(p.oid) as def from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'app' and p.proname in ('harness_job', 'job_origin', 'harness_label');

-- N04 the source of the voice-session predicate the restatement needs, and the offices columns (to separate his office from the others without naming anyone).
select p.proname, pg_get_functiondef(p.oid) as def from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'app' and p.proname = 'harness_voice_session';

-- N05 columns of public.offices.
select column_name, data_type from information_schema.columns where table_schema = 'public' and table_name = 'offices' order by ordinal_position;

-- N12 every blocker by state (the unfiltered table).
select state, count(*) as n from public.blockers group by state order by 2 desc;

-- N13 open blockers split by whose office they are in and by the cheap harness witnesses the table itself holds (no function call).
select o.kind as office_kind, count(*) as open_total, count(*) filter (where j.job_id is null) as no_job, count(*) filter (where j.synthetic or j.is_fixture) as job_flagged_harness, count(*) filter (where coalesce(p.is_fixture, false)) as project_fixture from public.blockers b left join public.offices o on o.office_id = b.office_id left join public.jobs j on j.job_id = b.job_id left join public.projects p on p.project_id = b.project_id where b.state = 'open' group by 1 order by 2 desc;

-- N14 open blockers by age bucket and by whether the question was ever put to him (asked_at set) and how many times.
select case when b.created_at > now() - interval '2 days' then 'a. under 2 days' when b.created_at > now() - interval '7 days' then 'b. 2 to 7 days' when b.created_at > now() - interval '30 days' then 'c. 7 to 30 days' else 'd. over 30 days' end as age, count(*) as n, count(*) filter (where b.asked_at is null) as never_asked, count(*) filter (where b.ask_attempts > 0) as ask_attempted from public.blockers b where b.state = 'open' group by 1 order by 1;

-- N16 resolved blockers still carrying work (a resolved question whose job is parked): is anything counted that is already answered?
select count(*) as resolved_but_job_paused from public.blockers b join public.jobs j on j.job_id = b.job_id where b.state <> 'open' and j.state::text = 'paused';

-- N20 the RESTATED harness predicate (N03/N04 inline, with the parent chain) over every open blocker, by office kind, whether the office has a login,
--     and verdict; with age, deadline, whether the work can continue and whether the question was ever put to him. Counts only.
with recursive chain as (select j.job_id as start_id, j.job_id, j.parent_job_id, 0 as depth from public.jobs j where j.job_id in (select job_id from public.blockers where state = 'open') union all select c.start_id, p.job_id, p.parent_job_id, c.depth + 1 from chain c join public.jobs p on p.job_id = c.parent_job_id where c.depth < 64), flag as (select ch.start_id, bool_or(j.synthetic or j.is_fixture or coalesce(pr.is_fixture, false) or (j.pinned_config ->> 'origin_namespace') = 'verify' or exists (select 1 from public.inbound_commands c where c.command_id = nullif(j.pinned_config ->> 'command_id', '')::uuid and c.office_id = j.office_id and (c.dedupe_key ~ '^(fixture|verify|probe|gate|ledger-proof)[-_.:]' or c.dedupe_key ~ ':(fixture|verify|probe|gate)[-_.:]' or (c.dedupe_key like 'voice:turn:%' and split_part(split_part(c.dedupe_key, ':', 3), '.', 1) !~ '^s[a-z0-9]{1,10}$') or c.context ->> 'visitor' is not null))) as harness from chain ch join public.jobs j on j.job_id = ch.job_id left join public.projects pr on pr.project_id = j.project_id group by ch.start_id) select o.kind as office_kind, (o.auth_user_id is null) as no_login, coalesce(f.harness, false) as harness, count(*) as n, count(*) filter (where b.real_deadline is not null and b.real_deadline <= now()) as overdue, count(*) filter (where b.created_at > now() - interval '2 days') as under_2d, count(*) filter (where b.created_at > now() - interval '7 days') as under_7d, count(*) filter (where b.work_can_continue) as work_continues, count(*) filter (where b.asked_at is null) as never_asked, count(*) filter (where b.ask_attempts > 0) as ask_attempted from public.blockers b left join public.offices o on o.office_id = b.office_id left join flag f on f.start_id = b.job_id where b.state = 'open' group by 1, 2, 3 order by 1, 2, 3;

-- N22 the person-kind offices by age order (an ordinal, never an identifier): how many offices, and how many open blockers sit in each ordinal.
with recursive chain as (select j.job_id as start_id, j.job_id, j.parent_job_id, 0 as depth from public.jobs j where j.job_id in (select job_id from public.blockers where state = 'open') union all select c.start_id, p.job_id, p.parent_job_id, c.depth + 1 from chain c join public.jobs p on p.job_id = c.parent_job_id where c.depth < 64), flag as (select ch.start_id, bool_or(j.synthetic or j.is_fixture or coalesce(pr.is_fixture, false) or (j.pinned_config ->> 'origin_namespace') = 'verify' or exists (select 1 from public.inbound_commands c where c.command_id = nullif(j.pinned_config ->> 'command_id', '')::uuid and c.office_id = j.office_id and (c.dedupe_key ~ '^(fixture|verify|probe|gate|ledger-proof)[-_.:]' or c.dedupe_key ~ ':(fixture|verify|probe|gate)[-_.:]' or (c.dedupe_key like 'voice:turn:%' and split_part(split_part(c.dedupe_key, ':', 3), '.', 1) !~ '^s[a-z0-9]{1,10}$') or c.context ->> 'visitor' is not null))) as harness from chain ch join public.jobs j on j.job_id = ch.job_id left join public.projects pr on pr.project_id = j.project_id group by ch.start_id), ord as (select o.office_id, o.state, row_number() over (order by o.created_at) as ordinal from public.offices o where o.kind = 'person') select ord.ordinal, ord.state, count(b.blocker_id) as open_blockers, count(b.blocker_id) filter (where not coalesce(f.harness, false)) as not_harness from ord left join public.blockers b on b.office_id = ord.office_id and b.state = 'open' left join flag f on f.start_id = b.job_id group by 1, 2 order by 1;

-- N21 the NOT-harness open blockers by what answering performs (a code-valued kind), the state of the job behind them and the specialist who raised them.
with recursive chain as (select j.job_id as start_id, j.job_id, j.parent_job_id, 0 as depth from public.jobs j where j.job_id in (select job_id from public.blockers where state = 'open') union all select c.start_id, p.job_id, p.parent_job_id, c.depth + 1 from chain c join public.jobs p on p.job_id = c.parent_job_id where c.depth < 64), flag as (select ch.start_id, bool_or(j.synthetic or j.is_fixture or coalesce(pr.is_fixture, false) or (j.pinned_config ->> 'origin_namespace') = 'verify' or exists (select 1 from public.inbound_commands c where c.command_id = nullif(j.pinned_config ->> 'command_id', '')::uuid and c.office_id = j.office_id and (c.dedupe_key ~ '^(fixture|verify|probe|gate|ledger-proof)[-_.:]' or c.dedupe_key ~ ':(fixture|verify|probe|gate)[-_.:]' or (c.dedupe_key like 'voice:turn:%' and split_part(split_part(c.dedupe_key, ':', 3), '.', 1) !~ '^s[a-z0-9]{1,10}$') or c.context ->> 'visitor' is not null))) as harness from chain ch join public.jobs j on j.job_id = ch.job_id left join public.projects pr on pr.project_id = j.project_id group by ch.start_id) select o.kind as office_kind, coalesce(b.on_answer ->> 'kind', '(resumes the job or none)') as answer_kind, jb.state::text as job_state, b.originating_agent, (b.standing_tool is not null) as offers_standing_yes, count(*) as n, min(b.created_at)::date as oldest, max(b.created_at)::date as newest from public.blockers b left join public.offices o on o.office_id = b.office_id left join flag f on f.start_id = b.job_id left join public.jobs jb on jb.job_id = b.job_id where b.state = 'open' and not coalesce(f.harness, false) group by 1, 2, 3, 4, 5 order by 6 desc;
